// FE 2026-11-25 19:00 - La iglesia que no le abrio a Pedro (Hechos 12). Visual de paz: camara que respira, fundidos de luz, polvo de luz.
import React from 'react';
import {useS, en, T, DUR, golpe, Easing, interpolate, clamp, AbsoluteFill, Camara, tono, h} from './kit';

export const SUBS = {arriba: 230, acento: '#ffe2a8'};

// ---------- tiempos atados a la voz ----------
const tCarcel = en('cárcel'), tDormido = en('dormido'), tDos1 = en('dos', 1), tSold = en('soldados'), tAtado = en('atado'), tCad1 = en('cadenas', 1);
const tDia = en('día'), tHer = en('Herodes'), tMat = en('pueblo'), tAng = en('ángel', 1), tDesp = en('despertó'), tCad2 = en('cadenas', 2), tCay = en('cayeron');
const tPu2 = en('puerta', 2), tHie = en('hierro'), tCiu = en('ciudad'), tAbr = en('abrió', 1), tCam = en('caminó'), tFue = en('Fue');
const tMaria = en('María'), tOr = en('orando'), tToco = en('Tocó'), tSalio = en('salió'), tRode = en('Rode'), tReco = en('Reconoció'), tAleg = en('alegría');
const tNoAb = en('abrió', 2), tCorrio = en('corrió'), tAdentro = en('adentro');
const tY = en('qué', 2), tEstas = en('estás'), tLoca = en('loca'), tInsist = en('insistió'), tAng2 = en('ángel', 2), tMientras = en('Mientras'), tFijate = en('Fíjate');
const tPid = en('orando', 2), tLlego = en('llegó'), tUnica = en('única'), tBiblia = en('Biblia'), tGuardo = en('guardó'), tNombre = en('nombre');
const tSi = en('Si'), tOras = en('oras'), tSorp = en('sorprendas'), tToque = en('toque'), tCrees = en('Crees'), tOramos = en('oramos'), tNO = en('no', 3);

// ---------- ayudas ----------
const cl = (v: number, a = 0, b = 1) => Math.max(a, Math.min(b, v));
const sm = (x: number) => { const k = cl(x); return k * k * (3 - 2 * k); };
const rp = (s: number, a: number, b: number) => sm((s - a) / Math.max(0.001, b - a));
const lerp = (a: number, b: number, k: number) => a + (b - a) * k;
const hx2 = (c: string) => [parseInt(c.slice(1, 3), 16), parseInt(c.slice(3, 5), 16), parseInt(c.slice(5, 7), 16)];
const mez = (a: string, b: string, k: number) => {
  const A = hx2(a), B = hx2(b);
  return '#' + A.map((v, i) => Math.round(v + (B[i] - v) * cl(k)).toString(16).padStart(2, '0')).join('');
};
const gol = (s: number, ts: number[], f = 30, d = 9) => ts.reduce((a, t) => a + Math.max(0, golpe(s, t, f, d)), 0);
const vis = (s: number, a: number, b: number) => Math.min(rp(s, a, a + 1), 1 - rp(s, b - 1, b));
const E = Easing.inOut(Easing.cubic);
const kf = (s: number, ts: number[], vs: number[]) => interpolate(s, ts, vs, {...clamp, easing: E});

const Glow: React.FC<{cx: number; cy: number; r: number; color: string; op?: number}> = ({cx, cy, r, color, op = 1}) => {
  const id = 'gl' + Math.round(cx) + '_' + Math.round(cy) + '_' + Math.round(r) + color.replace(/[^a-z0-9]/gi, '');
  return (
    <g style={{mixBlendMode: 'screen'}} opacity={op}>
      <defs><radialGradient id={id}><stop offset="0" stopColor={color} stopOpacity={0.85} /><stop offset="1" stopColor={color} stopOpacity={0} /></radialGradient></defs>
      <circle cx={cx} cy={cy} r={r} fill={`url(#${id})`} />
    </g>
  );
};

// ---------- personaje: vector liso, luz suave, ojos con punto blanco ----------
type Pt = [number, number];
type Est = {ropa: string; piel: string; pelo: string; manto?: string; barba?: string; panuelo?: string; trenza?: boolean; largo?: boolean; casco?: boolean; capa?: string; peto?: string; pierna?: string; bota?: string};
type PP = Est & {x: number; y: number; e?: number; s: number; id: string; mI?: Pt; mD?: Pt; caida?: number; paso?: number; inc?: number; ojos?: 'ab' | 'ce' | 'gr'; boca?: 'n' | 's' | 'o'; mira?: number; giro?: number; ceja?: number; halo?: string; fase?: number; oscuro?: number};

const L1 = 118;
const brazo = (sd: number, hx: number, hy: number) => {
  const sx = sd * 68, sy = -432;
  let dx = hx - sx, dy = hy - sy;
  let d = Math.hypot(dx, dy);
  const mx = 2 * L1 - 2;
  if (d > mx) { dx *= mx / d; dy *= mx / d; d = mx; }
  if (d < 30) { dx = 0; dy = 30; d = 30; }
  const base = Math.atan2(dy, dx), a = Math.acos(cl(d / (2 * L1), 0, 1));
  const c1 = {x: sx + L1 * Math.cos(base + a), y: sy + L1 * Math.sin(base + a)};
  const c2 = {x: sx + L1 * Math.cos(base - a), y: sy + L1 * Math.sin(base - a)};
  const el = sd * c1.x + 0.5 * c1.y > sd * c2.x + 0.5 * c2.y ? c1 : c2;
  return {sx, sy, ex: el.x, ey: el.y, hx: sx + dx, hy: sy + dy};
};

const Persona: React.FC<PP> = (p) => {
  const {x, y, e = 1, s, id, mI = [-96, -250], mD = [96, -250], caida = 0, paso = 0, inc = 0, ojos = 'ab', boca = 'n', mira = 0, giro = 0, ceja = 0, halo, fase = 0, oscuro = 0} = p;
  const dk = (c: string) => (oscuro > 0.01 ? mez(c, '#120806', oscuro) : c);
  const ropa = dk(p.ropa), piel = dk(p.piel), pelo = dk(p.pelo);
  const manto = p.manto ? dk(p.manto) : undefined, panuelo = p.panuelo ? dk(p.panuelo) : undefined, barba = p.barba ? dk(p.barba) : undefined, capa = p.capa ? dk(p.capa) : undefined;
  const largo = !!p.largo;
  const pierna = p.pierna ? dk(p.pierna) : piel;
  const bob = paso ? -Math.abs(Math.sin(paso)) * 9 : 0;
  const dy = 110 * caida + Math.sin(s * 1.8 + fase) * 3 + bob;
  const hem = lerp(largo ? -55 : -165, -125, caida);
  const bw = largo ? 112 : 98;
  const par = (s + fase * 1.7) % 3.6 < 0.12;
  const oj = ojos === 'ab' && par ? 'ce' : ojos;
  const aI = brazo(-1, mI[0], mI[1]), aD = brazo(1, mD[0], mD[1]);
  const oscu = mez(ropa, '#000000', 0.3), clar = mez(ropa, '#ffffff', 0.22);
  const pelS = mez(pelo, '#000000', 0.25);
  const ya = ceja === 2 ? [-592, -602, -596] : ceja === 1 ? [-572, -584, -589] : [-578, -586, -580];
  const Brz: React.FC<{a: ReturnType<typeof brazo>}> = ({a}) => {
    const mxk = a.ex + (a.hx - a.ex) * 0.36, myk = a.ey + (a.hy - a.ey) * 0.36;
    return (
      <g strokeLinecap="round" fill="none">
        <path d={`M${a.sx} ${a.sy}L${a.ex} ${a.ey}`} stroke={ropa} strokeWidth={40} />
        <path d={`M${a.ex} ${a.ey}L${a.hx} ${a.hy}`} stroke={piel} strokeWidth={30} />
        <path d={`M${a.ex} ${a.ey}L${mxk} ${myk}`} stroke={ropa} strokeWidth={36} />
        <circle cx={a.hx} cy={a.hy} r={22} fill={piel} stroke="none" />
      </g>
    );
  };
  return (
    <g transform={`translate(${x} ${y}) scale(${e}) rotate(${giro})`}>
      <defs>
        <linearGradient id={'g' + id} x1="0" y1="0" x2="1" y2="0"><stop offset="0" stopColor={clar} /><stop offset="0.55" stopColor={ropa} /><stop offset="1" stopColor={oscu} /></linearGradient>
        <radialGradient id={'k' + id} cx="0.35" cy="0.3" r="0.8"><stop offset="0" stopColor={mez(piel, '#ffffff', 0.28)} /><stop offset="1" stopColor={mez(piel, '#000000', 0.2)} /></radialGradient>
        {halo && <radialGradient id={'h' + id}><stop offset="0" stopColor={halo} stopOpacity={0.5} /><stop offset="1" stopColor={halo} stopOpacity={0} /></radialGradient>}
      </defs>
      {halo && <ellipse cx={0} cy={-300 + dy} rx={330} ry={420} fill={`url(#h${id})`} style={{mixBlendMode: 'screen'}} />}
      <ellipse cx={0} cy={0} rx={125} ry={20} fill="rgba(0,0,0,0.32)" />
      {caida < 0.97 && [-1, 1].map((k) => {
        const ph = paso + (k > 0 ? Math.PI : 0);
        const lift = paso ? Math.max(0, Math.sin(ph)) * 38 : 0;
        const st = paso ? Math.cos(ph) * 16 : 0;
        const fx = k * 32 + st * 0.5, fy = -14 - lift;
        return (
          <g key={k}>
            <path d={`M${k * 30} -250L${fx} ${fy}`} stroke={pierna} strokeWidth={32} strokeLinecap="round" />
            <ellipse cx={fx} cy={fy + 4} rx={36} ry={15} fill={p.bota ?? '#2b1d15'} />
          </g>
        );
      })}
      <g transform={`translate(0 ${dy})`}>
        {(manto || capa) && <path d={`M-92 -440Q-135 -290 -128 ${hem + 30}L128 ${hem + 30}Q135 -290 92 -440Z`} fill={mez(capa ?? manto!, '#000000', 0.2)} />}
        <path d={`M-72 -442Q-88 -330 -90 -250L${-bw} ${hem}Q0 ${hem + 16} ${bw} ${hem}L90 -250Q88 -330 72 -442Q0 -482 -72 -442Z`} fill={`url(#g${id})`} />
        <path d="M-88 -296L88 -296" stroke={oscu} strokeWidth={14} />
        {p.peto && <path d="M-68 -446Q0 -478 68 -446L62 -310Q0 -290 -62 -310Z" fill={dk(p.peto)} stroke={mez(p.peto, '#000000', 0.35)} strokeWidth={3} />}
        {manto && <path d="M-84 -446Q0 -508 84 -446L74 -372Q0 -412 -74 -372Z" fill={manto} />}
        <Brz a={aI} />
        <Brz a={aD} />
        <rect x={-20} y={-500} width={40} height={58} rx={14} fill={mez(piel, '#000000', 0.18)} />
        <g transform={`rotate(${inc} 0 -492)`}>
          {panuelo && <path d="M-66 -548Q-72 -646 0 -646Q72 -646 66 -548Q72 -480 44 -452L0 -474L-44 -452Q-72 -480 -66 -548Z" fill={panuelo} />}
          {p.casco && <path d="M-50 -652Q0 -742 50 -652Q0 -692 -50 -652Z" fill="#a8242c" />}
          <ellipse cx={0} cy={-548} rx={56} ry={64} fill={`url(#k${id})`} />
          {barba && <path d="M-54 -540Q-56 -470 0 -466Q56 -470 54 -540Q40 -508 0 -506Q-40 -508 -54 -540Z" fill={barba} />}
          {!panuelo && !p.casco && <path d="M-58 -552Q-62 -628 0 -626Q62 -628 58 -552Q48 -596 0 -596Q-48 -596 -58 -552Z" fill={pelo} />}
          {panuelo && <path d="M-60 -562Q0 -616 60 -562Q52 -600 0 -608Q-52 -600 -60 -562Z" fill={mez(panuelo, '#000000', 0.12)} />}
          {p.trenza && [0, 1, 2, 3, 4, 5].map((i) => <ellipse key={i} cx={50 + i * 3 + Math.sin(s * 2 + i) * 2} cy={-500 + i * 26} rx={14 - i} ry={16} fill={i % 2 ? pelo : pelS} />)}
          {p.casco && (
            <g>
              <path d="M-64 -556Q-70 -654 0 -656Q70 -654 64 -556Q40 -590 0 -592Q-40 -590 -64 -556Z" fill="#aeb7c6" stroke="#7e8798" strokeWidth={4} />
              <path d="M-64 -556L-60 -500L-44 -500L-48 -556ZM64 -556L60 -500L44 -500L48 -556Z" fill="#8f98a8" />
            </g>
          )}
          <g transform={`translate(${mira * 4} 0)`}>
            <ellipse cx={-34} cy={-526} rx={14} ry={8} fill="rgba(255,120,130,0.3)" />
            <ellipse cx={34} cy={-526} rx={14} ry={8} fill="rgba(255,120,130,0.3)" />
            {[-1, 1].map((sd) => {
              const ex = sd * 22;
              return (
                <g key={sd}>
                  {oj === 'ab' && <g><circle cx={ex} cy={-552} r={8.5} fill="#15110f" /><circle cx={ex + 2.8} cy={-555} r={3} fill="#fff" /></g>}
                  {oj === 'gr' && <g><circle cx={ex} cy={-552} r={13} fill="#15110f" /><circle cx={ex + 4} cy={-557} r={4.8} fill="#fff" /></g>}
                  {oj === 'ce' && <path d={`M${ex - 12} -553Q${ex} -541 ${ex + 12} -553`} stroke="#15110f" strokeWidth={4.5} fill="none" strokeLinecap="round" />}
                  <path d={`M${sd * 38} ${ya[0]}Q${sd * 24} ${ya[1]} ${sd * 8} ${ya[2]}`} stroke={mez(pelo, '#000000', 0.15)} strokeWidth={5} fill="none" strokeLinecap="round" />
                </g>
              );
            })}
            <path d="M2 -540Q8 -528 0 -523" stroke="rgba(0,0,0,0.25)" strokeWidth={4} fill="none" strokeLinecap="round" />
            {boca === 'n' && <path d="M-14 -511Q0 -505 14 -511" stroke="#7a2f26" strokeWidth={5} fill="none" strokeLinecap="round" />}
            {boca === 's' && <path d="M-22 -516Q0 -490 22 -516Q0 -508 -22 -516Z" fill="#5a1d18" stroke="#7a2f26" strokeWidth={4} strokeLinejoin="round" />}
            {boca === 'o' && <ellipse cx={0} cy={-509} rx={10} ry={13} fill="#4a1a14" />}
          </g>
        </g>
      </g>
    </g>
  );
};

const PEDRO: Est = {ropa: '#8a5e3a', manto: '#2f4a3a', piel: '#c8946a', pelo: '#9a9791', barba: '#aaa6a0'};
const RODE: Est = {ropa: '#f2c230', panuelo: '#f08a24', trenza: true, largo: true, piel: '#d9a074', pelo: '#15100c'};
const MARIA: Est = {ropa: '#5b3a73', manto: '#7e4aa0', panuelo: '#b9a7d0', largo: true, piel: '#d9aa86', pelo: '#bdb8c0'};
const GENTE: Est[] = [
  {ropa: '#2f7f86', piel: '#c58a5c', pelo: '#2a1c14', barba: '#2a1c14'},
  {ropa: '#c4566a', panuelo: '#f1d9b5', piel: '#e0a97d', pelo: '#3a2418', largo: true},
  RODE,
  {ropa: '#c9873a', piel: '#a8724a', pelo: '#4a3a2a', barba: '#8a8580'},
  MARIA,
  {ropa: '#4f7f3a', piel: '#b57b52', pelo: '#201510'},
  {ropa: '#3f6fb5', panuelo: '#e8e2d0', largo: true, piel: '#e8b890', pelo: '#3a2a20'},
  {ropa: '#9a4a32', barba: '#3a2a20', piel: '#8e5a3a', pelo: '#2a1c14'},
  {ropa: '#e08a5a', panuelo: '#7ab0a0', largo: true, piel: '#caa078', pelo: '#2a1c14'},
  {ropa: '#33466e', manto: '#8a7a5a', piel: '#d0a07a', pelo: '#2a2a2a'},
  {ropa: '#7c8a3a', panuelo: '#d8a05a', largo: true, piel: '#b88060', pelo: '#2a1c14'},
  {ropa: '#6a3a4c', barba: '#8a8580', piel: '#c28a60', pelo: '#6a6560'},
];

// ---------- capas de luz ----------
const Polvo: React.FC<{s: number; n?: number; color?: string; op?: number}> = ({s, n = 44, color = '#ffe9b8', op = 0.55}) => (
  <svg width={1080} height={1920} style={{position: 'absolute', left: 0, top: 0}}>
    {Array.from({length: n}).map((_, i) => {
      const sp = 14 + h(i) * 26;
      const x = h(i * 3 + 1) * 1180 - 50 + Math.sin(s * 0.5 + i * 1.7) * 36 + s * (h(i + 9) - 0.5) * 14;
      const y = 1980 - ((h(i * 5 + 2) * 2100 + s * sp) % 2100);
      const r = 2 + h(i * 7) * 4.5;
      const tw = 0.45 + 0.55 * Math.sin(s * 1.6 + i * 2.1) ** 2;
      return <circle key={i} cx={x} cy={y} r={r} fill={color} opacity={op * tw} />;
    })}
  </svg>
);

const Rayos: React.FC<{s: number; color?: string; op?: number; x?: number}> = ({s, color = '255,230,170', op = 0.13, x = -120}) => (
  <svg width={1080} height={1920} style={{position: 'absolute', left: 0, top: 0, mixBlendMode: 'screen'}}>
    <defs>
      <linearGradient id="rayoG" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor={`rgb(${color})`} stopOpacity={1} /><stop offset="1" stopColor={`rgb(${color})`} stopOpacity={0} /></linearGradient>
    </defs>
    {[0, 1, 2, 3].map((i) => {
      const sw = Math.sin(s * 0.35 + i * 1.3) * 70;
      const x0 = x + i * 300 + sw * 0.4;
      return <polygon key={i} points={`${x0},-50 ${x0 + 120},-50 ${x0 + 520 + sw},1700 ${x0 + 170 + sw},1700`} fill="url(#rayoG)" opacity={op * (0.55 + 0.45 * Math.sin(s * 0.7 + i * 1.9))} />;
    })}
  </svg>
);

const Luz: React.FC<{s: number; t: number; color?: string; w?: number}> = ({s, t, color = 'rgba(255,236,190,0.9)', w = 1.0}) => {
  const a = Math.max(0, 1 - Math.abs(s - t) / w) * 0.42;
  return a > 0.001 ? <AbsoluteFill style={{background: `radial-gradient(circle at 50% 55%, ${color} 0%, rgba(255,236,190,0) 72%)`, opacity: a, mixBlendMode: 'screen'}} /> : null;
};

const Sc: React.FC<{op: number; s: number; children: React.ReactNode}> = ({op, s, children}) =>
  op <= 0.001 ? null : (
    <AbsoluteFill style={{opacity: op, overflow: 'hidden'}}>
      <AbsoluteFill style={{transform: `scale(${1 + 0.012 * Math.sin(s * 0.8)}) translate(${Math.sin(s * 0.45) * 5}px, ${Math.cos(s * 0.37) * 4}px)`}}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );

// ---------- fachada de noche: puerta, luna, gato ----------
const Puerta: React.FC<{cx: number; luz: number; a: number; s: number; id: string; kn: number; sombras?: boolean}> = ({cx, luz, a, s, id, kn, sombras}) => {
  const hxx = cx - 190;
  const arco = `M${cx - 190} 1520V1090Q${cx - 190} 900 ${cx} 900Q${cx + 190} 900 ${cx + 190} 1090V1520Z`;
  const top = (dx: number) => 1090 - 190 * Math.sqrt(Math.max(0, 1 - (dx / 190) ** 2));
  const kk = 1 - 0.88 * a;
  return (
    <g>
      <defs>
        <clipPath id={'cp' + id}><path d={arco} /></clipPath>
        <linearGradient id={'lg' + id} x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#fff2c6" /><stop offset="1" stopColor="#e8a050" /></linearGradient>
        <linearGradient id={'wd' + id} x1="0" y1="0" x2="1" y2="0"><stop offset="0" stopColor="#6a4528" /><stop offset="1" stopColor="#3f2916" /></linearGradient>
        <linearGradient id={'sp' + id} x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#ffd48a" stopOpacity={0.9} /><stop offset="1" stopColor="#ffd48a" stopOpacity={0} /></linearGradient>
      </defs>
      <path d={`M${cx - 214} 1520V1090Q${cx - 214} 876 ${cx} 876Q${cx + 214} 876 ${cx + 214} 1090V1520Z`} fill="#51496a" />
      <path d={arco} fill="#1a1020" />
      <path d={arco} fill={`url(#lg${id})`} opacity={cl(luz * a * 1.1)} />
      <polygon points={`${cx - 190},1520 ${cx + 190},1520 ${cx + 460},1920 ${cx - 460},1920`} fill={`url(#sp${id})`} opacity={luz * (0.16 + 0.5 * a)} style={{mixBlendMode: 'screen'}} />
      <g transform={`translate(${hxx} 0) scale(${kk} 1) translate(${-hxx} 0)`}>
        <path d={arco} fill={`url(#wd${id})`} />
        <g clipPath={`url(#cp${id})`}>
          {[-127, -63, 0, 63, 127].map((dx) => (
            <g key={dx}>
              <path d={`M${cx + dx} ${top(dx) + 10}V1515`} stroke="#ffd27a" strokeWidth={14} opacity={0.22 * luz * (1 - a)} />
              <path d={`M${cx + dx} ${top(dx) + 10}V1515`} stroke="#fff0c0" strokeWidth={5} opacity={0.95 * luz * (1 - a)} />
            </g>
          ))}
          {sombras && [0, 1, 2].map((j) => <rect key={j} x={cx - 230 + ((s * 70 + j * 190) % 560)} y={900} width={54} height={620} fill="#3d2a1a" opacity={0.85 * luz} />)}
          <rect x={cx - 190} y={1010} width={380} height={26} fill="#241e2b" />
          <rect x={cx - 190} y={1370} width={380} height={26} fill="#241e2b" />
          {[-150, -75, 0, 75, 150].map((dx) => <g key={dx}><circle cx={cx + dx} cy={1023} r={6} fill="#6c6578" /><circle cx={cx + dx} cy={1383} r={6} fill="#6c6578" /></g>)}
        </g>
        <circle cx={cx} cy={1190} r={30} fill="#2b2630" />
        <g transform={`rotate(${kn * 20} ${cx} 1190)`}><circle cx={cx} cy={1226} r={27} fill="none" stroke="#9a93a8" strokeWidth={9} /></g>
      </g>
    </g>
  );
};

const Fachada: React.FC<{s: number; modo: 'toca' | 'abrazo'; a0: number; kt: number[]; vecT?: number}> = ({s, modo, a0, kt, vecT = 1e9}) => {
  const toca = modo === 'toca';
  const kn = gol(s, kt, 34, 10);
  const ks = [-3, -2, -1, 0, 1, 2, 3, 4];
  const gx = ((s - T(0)) * 150) % 1900 - 400;
  const tapD = gol(s, kt, 34, 12);
  const salto = (t: number) => Math.abs(golpe(s, t, 18, 5)) * 38;
  return (
    <svg width={4400} height={7000} viewBox="-1600 -2200 4400 7000" style={{position: 'absolute', left: -1600, top: -2200}}>
      <defs>
        <linearGradient id="fCielo" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#070b26" /><stop offset="0.75" stopColor="#1c2358" /><stop offset="1" stopColor="#3b3f7e" /></linearGradient>
        <pattern id="fLad" width={150} height={70} patternUnits="userSpaceOnUse"><rect width={150} height={70} fill="#3d3652" /><path d="M0 0H150M0 35H150M0 0V35M75 35V70" stroke="#2b2540" strokeWidth={4} fill="none" /></pattern>
