const Cadena: React.FC<{p: Pt; q: Pt; s: number; i: number}> = ({p, q, s, i}) => {
  const n = 5, links = [];
  for (let j = 0; j < n; j++) {
    const u = (j + 0.5) / n;
    const x0 = lerp(p[0], q[0], u), y0 = lerp(p[1], q[1], u) + 22 * 4 * u * (1 - u);
    const dt = s - (tCay + 0.05 * j + 0.02 * i);
    let yy = y0, rot = j % 2 ? 90 : 0, xx = x0;
    if (dt > 0) {
      const g = 1500, fl = 1740;
      const tHit = Math.sqrt(Math.max(0.0001, 2 * (fl - y0) / g));
      if (dt < tHit) yy = y0 + 0.5 * g * dt * dt;
      else { const u2 = dt - tHit; yy = fl - Math.max(0, 0.4 * g * tHit * u2 - 0.5 * g * u2 * u2); }
      xx = x0 + (j - 2) * 22 * Math.min(1, dt * 2);
      rot += dt * 420 * (j % 2 ? 1 : -1) * Math.exp(-dt * 1.2);
    }
    links.push(<ellipse key={j} cx={xx} cy={yy} rx={17} ry={9} fill="none" stroke="#98a2b6" strokeWidth={6} transform={`rotate(${rot} ${xx} ${yy})`} />);
  }
  return <g>{links}</g>;
};

