        <circle cx={1000} cy={520} r={104} fill="#f4f0e0" />
        <circle cx={970} cy={495} r={18} fill="#e0dac4" /><circle cx={1030} cy={550} r={26} fill="#e0dac4" />
        {[0, 1, 2].map((i) => <ellipse key={i} cx={((s * (10 + i * 4) + i * 1100) % 3800) - 900} cy={300 + i * 200} rx={260 + i * 60} ry={30} fill="rgba(120,130,190,0.3)" />)}
        {/* ciudad lejana */}
        <path d="M-800 1500V1180H-640V1100H-480V1220H-300V1060H-120V1180H80V1500ZM1150 1500V1160H1290V1060H1420V1200H1560V1120H2800V1500Z" fill="#161a3a" />
        {/* muralla y torres */}
        <rect x={-800} y={760} width={1950} height={760} fill="url(#kLad)" />
        {Array.from({length: 22}).map((_, i) => <rect key={i} x={-790 + i * 90} y={712} width={52} height={52} fill="#4a4262" />)}
        <rect x={-60} y={420} width={320} height={1100} fill="url(#kLad)" /><rect x={-80} y={390} width={360} height={46} fill="#5a5274" />
        <rect x={860} y={420} width={320} height={1100} fill="url(#kLad)" /><rect x={840} y={390} width={360} height={46} fill="#5a5274" />
        {[40, 960].map((tx) => <g key={tx}><rect x={tx + 90} y={560} width={50} height={110} rx={25} fill="#ffb15a" opacity={0.85 * (0.8 + 0.2 * Math.sin(s * 9 + tx))} /></g>)}
        <Glow cx={125} cy={615} r={260} color="#ff9a40" op={0.45} /><Glow cx={1025} cy={615} r={260} color="#ff9a40" op={0.45} />
        {/* suelo */}
        <rect x={-800} y={1500} width={3600} height={1100} fill="url(#kAdo)" />
        <polygon points="330,1500 790,1500 1300,2600 -200,2600" fill="rgba(160,150,210,0.22)" />
        <rect x={-800} y={1500} width={3600} height={36} fill="rgba(0,0,0,0.4)" />
        {/* luz detras de la puerta */}
        <path d={arc} fill="url(#kLuz)" opacity={0.25 + 0.75 * ab} />
        <g clipPath="url(#kArc)"><rect x={330 + (glint * 520 - 120)} y={800} width={70} height={700} fill="#ffffff" opacity={0.55 * Math.sin(glint * Math.PI)} transform={`skewX(-14)`} /></g>
        <polygon points="450,1500 670,1500 1000,1920 120,1920" fill="url(#kDest)" opacity={0.55 * ab} style={{mixBlendMode: 'screen'}} />
        <Glow cx={560} cy={1250} r={520} color="#fff3c8" op={0.85 * ab} />
        {leaf(-1)}
        {leaf(1)}
        {/* casa de Maria */}
        <rect x={1380} y={740} width={850} height={820} fill="#4d3f58" />
        <rect x={1380} y={700} width={850} height={50} fill="#5e4f6c" />
        <rect x={1380} y={760} width={850} height={800} fill="url(#kLad)" opacity={0.35} />
        <path d="M1570 1500V1290Q1570 1190 1680 1190Q1790 1190 1790 1290V1500Z" fill="#3a2a1c" />
        <path d="M1600 1500V1300M1680 1500V1215M1760 1500V1300" stroke="#ffd27a" strokeWidth={5} opacity={0.55 + 0.2 * Math.sin(s * 5)} />
        <rect x={WIN.x - 140} y={WIN.y - 175} width={280} height={350} rx={20} fill="#2a1c14" />
        <g clipPath="url(#kWin)">
          <rect x={WIN.x - 115} y={WIN.y - 150} width={230} height={300} fill="url(#kVen)" opacity={0.7 + 0.3 * lampP} />
          {[-78, -26, 26, 78].map((dx, i) => (
            <g key={dx} transform={`translate(${WIN.x + dx} ${WIN.y + 70 + Math.sin(s * 1.4 + i * 1.3) * 6})`}>
              <circle cx={0} cy={-34} r={26} fill="#3a1f12" />
              <path d="M-40 60Q-44 -10 0 -12Q44 -10 40 60Z" fill="#3a1f12" />
              <path d={`M-10 14Q0 ${-4 + Math.sin(s * 2 + i) * 5} 10 14`} stroke="#6b3a1c" strokeWidth={6} fill="none" />
            </g>
          ))}
          <path d={`M${WIN.x} ${WIN.y - 80}Q${WIN.x - 14} ${WIN.y - 110} ${WIN.x} ${WIN.y - 140 + Math.sin(s * 14) * 5}Q${WIN.x + 14} ${WIN.y - 110} ${WIN.x} ${WIN.y - 80}Z`} fill="#fff0a8" />
        </g>
        <Glow cx={WIN.x} cy={WIN.y} r={420 * lampP} color="#ffb04a" op={0.7} />
        <polygon points={`${WIN.x - 130},${WIN.y + 170} ${WIN.x + 130},${WIN.y + 170} ${WIN.x + 330},1920 ${WIN.x - 330},1920`} fill="url(#kDest)" opacity={0.28 * lampP} style={{mixBlendMode: 'screen'}} />
        {[1400, 2200].map((vx, i) => <g key={vx}><rect x={vx} y={1000 + i * 40} width={70} height={100} rx={30} fill="#ffb04a" opacity={0.5 + 0.3 * Math.sin(s * 2 + i * 2)} /></g>)}
        {s > tAbr + 0.3 && <g opacity={pOp}><Persona x={px} y={py} e={pe} s={s} id="pcc" {...PEDRO} halo="#fff3cf" paso={walking ? s * 7 : 0} mI={walking ? [-100, -250 + 50 * Math.sin(s * 7)] : [-96, -250]} mD={walking ? [100, -250 - 50 * Math.sin(s * 7)] : [96, -250]} ojos="ab" boca="s" ceja={0} giro={s > tFue ? 5 : 0} mira={s > tFue ? 1 : 0} /></g>}
      </svg>
    </AbsoluteFill>
  );
};

// ---------- sala de la casa de Maria ----------
const POS = GENTE.map((_, i) => {
  const th = ((i * 30 + 15) * Math.PI) / 180;
  const y = 1545 + 100 * Math.sin(th);
  return {x: 700 + 430 * Math.cos(th), y, e: 0.64 + 0.3 * cl((y - 1445) / 200)};
});
const KNOCK = Array.from({length: 46}).map((_, k) => tToco + k * 0.66);
const DOOR = {x: 1700, base: 1560};

const Sala: React.FC<{s: number}> = ({s}) => {
  const kg = gol(s, KNOCK, 34, 10);
  const osc = rp(s, tUnica - 0.3, tUnica + 0.5);
  const lamp = (x: number, y: number, i: number) => {
    const f = 0.85 + 0.12 * Math.sin(s * 7 + i * 2.1) + 0.08 * Math.sin(s * 13 + i);
    const br = 1 + 0.35 * rp(s, tOr, tOr + 0.8) * (1 - osc * 0.5);
    return (
      <g key={i}>
        <path d={`M${x} -20V${y - 50}`} stroke="#3a2a1c" strokeWidth={6} />
        <path d={`M${x - 34} ${y}Q${x} ${y + 44} ${x + 34} ${y}Z`} fill="#8a5a2c" />
        <path d={`M${x} ${y}Q${x - 14} ${y - 22} ${x} ${y - 50 + Math.sin(s * 12 + i) * 4}Q${x + 14} ${y - 22} ${x} ${y}Z`} fill="#ffe28a" />
        <Glow cx={x} cy={y - 14} r={340 * f * br} color="#ffb04a" op={0.62 * (1 - 0.5 * osc)} />
      </g>
    );
  };
  // postura general de una persona (reza, se levanta, discute, pide)
  const gen = (i: number) => {
    const cai = s < tY + 0.05 ? 1 : s < tPid ? 1 - rp(s, tY + 0.1 + i * 0.05, tY + 0.9 + i * 0.05) : rp(s, tPid + i * 0.04, tPid + 0.8 + i * 0.04);
    const up = rp(s, tOr, tOr + 0.8) * (1 - rp(s, tToco + 0.3, tToco + 1.0)) + rp(s, tPid, tPid + 0.8);
    const rez = cai > 0.5;
    const sw = Math.sin(s * 3 + i * 1.7), sw2 = Math.sin(s * 2.4 + i * 2.3);
    let mI: Pt = rez ? [-lerp(14, 56, up), lerp(-385, -475, up)] : [-(80 + 30 * sw), -330 + 40 * sw2];
    let mD: Pt = rez ? [lerp(14, 56, up), lerp(-385, -475, up)] : [80 + 30 * sw2, -330 + 40 * sw];
    let inc = rez ? 4 * Math.sin(s * 0.9 + i) : 0;
    const asust = s > tToco && s < tToco + 1.2;
    let ojos: 'ab' | 'ce' | 'gr' = rez ? (asust ? 'gr' : 'ce') : 'ab';
    if (asust) inc += 8 * golpe(s, tToco, 30, 6);
    let ceja = rez ? 1 : 1;
    const habla = !rez && s > tY && s < tMientras + 3 && Math.sin(s * 8 + i * 2) > 0.2;
    if (i === 3 || i === 7) { if (s > tEstas - 0.2 && s < tLoca + 1.0) { inc = 14 * Math.sin(s * 9 + i); mI = [-120, -300]; mD = [120, -300]; } }
    if (i === 1 && s > tLoca - 0.3 && s < tLoca + 1.6) { ceja = 2; mD = [-30, -380]; ojos = 'gr'; }
    if (i === 0 && s > tAng2 - 0.2 && s < tAng2 + 1.8) { mD = [80, -700]; ceja = 2; }
    return {caida: cai, mI, mD, inc, ojos, ceja, boca: (habla ? 'o' : 'n') as 'o' | 'n'};
  };
  // Rode
  const RT = [0, tSalio + 0.3, tRode + 0.2, tCorrio - 0.05, tAdentro + 0.9, tFijate - 0.6, tFijate + 0.6, tNombre, tNombre + 0.7];
  const RX = [POS[2].x, POS[2].x, 1555, 1555, 880, 880, 700, 700, 1555];
  const RY = [POS[2].y, POS[2].y, 1600, 1600, 1650, 1650, 1548, 1548, 1600];
  const rx = (t: number) => kf(t, RT, RX), ry = (t: number) => kf(t, RT, RY);
  const vx = (rx(s + 0.05) - rx(s - 0.05)) / 0.1;
  const mueve = Math.abs(vx) > 25 || Math.abs((ry(s + 0.05) - ry(s - 0.05)) / 0.1) > 25;
  const rodePose = () => {
    if (s < tSalio - 0.1) return {...gen(2), paso: 0, giro: 0, boca: 'n' as 'n' | 's' | 'o'};
    const cai = 1 - rp(s, tSalio - 0.1, tSalio + 0.5);
    const base = {caida: cai, paso: mueve ? s * 13 : 0, giro: cl(vx * 0.011, -9, 9), inc: 0, ojos: 'ab' as 'ab' | 'ce' | 'gr', boca: 'n' as 'n' | 's' | 'o', ceja: 1, mI: [-96, -250] as Pt, mD: [96, -250] as Pt};
    if (s < tRode + 0.3) return {...base, mI: [-100, -250 + 40 * Math.sin(s * 13)] as Pt, mD: [100, -250 - 40 * Math.sin(s * 13)] as Pt, boca: 'o' as const};
    if (s < tReco) return {...base, boca: 'o' as const, ojos: 'gr' as const};
    if (s < tAleg) return {...base, giro: 5, inc: 14, ojos: 'gr' as const, boca: 'o' as const, ceja: 2, mD: [150, -440] as Pt, mI: [-30, -330] as Pt};
    if (s < tNoAb) return {...base, ojos: 'gr' as const, boca: 's' as const, ceja: 2, mI: [-22, -500] as Pt, mD: [22, -500] as Pt};
    if (s < tCorrio - 0.05) return {...base, inc: 12 * Math.sin(s * 20), boca: 'o' as const, ceja: 1, ojos: 'gr' as const, mI: [-130, -380] as Pt, mD: [130, -380] as Pt};
    if (s < tAdentro + 0.9) return {...base, boca: 'o' as const, mI: [-110, -300 + 60 * Math.sin(s * 13)] as Pt, mD: [110, -300 - 60 * Math.sin(s * 13)] as Pt};
    if (s < tFijate - 0.6) return {...base, boca: Math.sin(s * 9) > 0 ? ('o' as const) : ('n' as const), ceja: 1, mI: [-130, -420 + 70 * Math.sin(s * 7)] as Pt, mD: [130, -420 + 70 * Math.sin(s * 7 + 1.7)] as Pt};
    if (s < tNombre) return {...base, boca: 's' as const, ceja: 0, inc: -4, mI: [-16, -380] as Pt, mD: [16, -380] as Pt};
    return {...base, boca: 's' as const, ceja: 0, mI: [-110, -300 + 60 * Math.sin(s * 15)] as Pt, mD: [110, -300 - 60 * Math.sin(s * 15)] as Pt};
  };
  const rp0 = rodePose();
  const rSalto = Math.abs(golpe(s, tAleg, 18, 5)) * 34;
  const rodeY = ry(s) - rSalto;
  const rodeE = 0.64 + 0.3 * cl((ry(s) - 1445) / 200) + 0.04;
  const items: {y: number; n: React.ReactNode}[] = [];
  for (let i = 0; i < GENTE.length; i++) {
    if (i === 2) continue;
    const g = gen(i);
    items.push({y: POS[i].y, n: <Persona key={i} x={POS[i].x} y={POS[i].y} e={POS[i].e} s={s} id={'sp' + i} {...GENTE[i]} {...g} fase={i} oscuro={0.55 * osc} />});
  }
  items.push({y: ry(s) + 0.1, n: <g key="rode"><Glow cx={rx(s)} cy={ry(s) - 280} r={360} color="#ffd9a0" op={0.9 * osc} /><Persona x={rx(s)} y={rodeY} e={rodeE} s={s} id="spr" {...RODE} {...rp0} fase={2} halo={osc > 0.3 ? '#ffe2a8' : undefined} /></g>});
  items.sort((a, b) => a.y - b.y);
  const puertaAb = rp(s, tNombre + 0.5, tNombre + 1.0);
  const hxd = DOOR.x - 160;
  const dArc = `M${DOOR.x - 160} ${DOOR.base}V1260Q${DOOR.x - 160} 1060 ${DOOR.x} 1060Q${DOOR.x + 160} 1060 ${DOOR.x + 160} 1260V${DOOR.base}Z`;
  const dFlash = rp(s, tLlego, tLlego + 0.15) * (1 - rp(s, tLlego + 0.15, tLlego + 0.8));
  const puntosRez = items.length;
  void puntosRez;
  const th = rp(s, tAng2 - 0.1, tAng2 + 0.5) * (1 - rp(s, tAng2 + 2.2, tAng2 + 2.8));
  return (
    <AbsoluteFill>
      <svg width={2400} height={2600} style={{position: 'absolute', left: 0, top: 0}}>
        <defs>
          <linearGradient id="sPared" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#6f4322" /><stop offset="1" stopColor="#3e2412" /></linearGradient>
          <linearGradient id="sSuelo" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#5a3a22" /><stop offset="1" stopColor="#2e1c10" /></linearGradient>
          <linearGradient id="sLuna" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#bcd0ff" stopOpacity={0.55} /><stop offset="1" stopColor="#bcd0ff" stopOpacity={0} /></linearGradient>
          <linearGradient id="sPl" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stopColor="#6a4528" /><stop offset="1" stopColor="#3b2614" /></linearGradient>
          <clipPath id="sCp"><path d={dArc} /></clipPath>
        </defs>
        <rect width={2400} height={1600} fill="url(#sPared)" />
        {[200, 900, 1500, 2150].map((vx, i) => <path key={i} d={`M${vx - 120} 1400V900Q${vx - 120} 700 ${vx} 700Q${vx + 120} 700 ${vx + 120} 900V1400Z`} fill="rgba(0,0,0,0.18)" />)}
        <rect width={2400} height={170} fill="#3a2410" />
        {Array.from({length: 9}).map((_, i) => <rect key={i} x={i * 300 + 20} y={0} width={34} height={170} fill="#2a1808" />)}
        <rect y={1500} width={2400} height={1100} fill="url(#sSuelo)" />
        {Array.from({length: 9}).map((_, i) => <path key={i} d={`M0 ${1540 + i * 46}H2400`} stroke="rgba(0,0,0,0.28)" strokeWidth={4} />)}
        <ellipse cx={700} cy={1570} rx={560} ry={150} fill="#7a2e2e" />
        <ellipse cx={700} cy={1570} rx={500} ry={125} fill="none" stroke="#d9a84a" strokeWidth={8} />
        <ellipse cx={700} cy={1570} rx={380} ry={92} fill="none" stroke="#d9a84a" strokeWidth={4} opacity={0.7} />
        {[360, 1100].map((lx, i) => lamp(lx, 520 + i * 40, i))}
        {lamp(730, 460, 2)}
        {/* puerta de la casa por dentro */}
        <path d={`M${DOOR.x - 190} ${DOOR.base}V1260Q${DOOR.x - 190} 1030 ${DOOR.x} 1030Q${DOOR.x + 190} 1030 ${DOOR.x + 190} 1260V${DOOR.base}Z`} fill="#2a1a0e" />
        <path d={dArc} fill="#e8f0ff" opacity={puertaAb} />
        <polygon points={`${DOOR.x - 160},${DOOR.base} ${DOOR.x + 160},${DOOR.base} ${DOOR.x + 320},1700 ${DOOR.x - 320},1700`} fill="url(#sLuna)" opacity={0.7} />
        <rect x={DOOR.x - 120 + Math.sin(s * 1.3) * 22} y={DOOR.base - 8} width={50} height={18} rx={9} fill="#0b0a14" opacity={0.7} />
        <rect x={DOOR.x + 40 + Math.sin(s * 1.3) * 22} y={DOOR.base - 8} width={50} height={18} rx={9} fill="#0b0a14" opacity={0.7} />
        <g transform={`translate(${hxd} 0) scale(${1 - 0.9 * puertaAb} 1) translate(${-hxd} 0) translate(${kg * 3} 0)`}>
          <path d={dArc} fill="url(#sPl)" />
          <g clipPath="url(#sCp)">
            {[-96, -48, 0, 48, 96].map((dx) => <path key={dx} d={`M${DOOR.x + dx} 1060V${DOOR.base}`} stroke="#241408" strokeWidth={5} />)}
            <rect x={DOOR.x - 160} y={1200} width={320} height={22} fill="#241e2b" />
            <rect x={DOOR.x - 160} y={1440} width={320} height={22} fill="#241e2b" />
          </g>
          <rect x={DOOR.x - 215} y={1290} width={430} height={34} rx={8} fill="#8a6a44" stroke="#4a3220" strokeWidth={4} />
          <circle cx={DOOR.x} cy={1180} r={22} fill="#2b2630" />
          <g transform={`rotate(${kg * 20} ${DOOR.x} 1180)`}><circle cx={DOOR.x} cy={1210} r={20} fill="none" stroke="#9a93a8" strokeWidth={7} /></g>
        </g>
        {KNOCK.filter((t) => s > t && s < t + 0.7).map((t, i) => <circle key={i} cx={DOOR.x} cy={1180} r={30 + (s - t) * 420} fill="none" stroke="#bcd0ff" strokeWidth={6} opacity={0.6 * (1 - (s - t) / 0.7)} />)}
        <Glow cx={DOOR.x} cy={1250} r={420} color="#bcd0ff" op={0.35 * (1 - puertaAb) + 0.6 * dFlash} />
        <rect width={2400} height={2600} fill="#1a0a04" opacity={0.4 * osc} />
        {items.map((it) => it.n)}
        {/* oraciones que suben */}
        {s > tPid && s < tUnica + 1.2 && GENTE.map((_, i) => i === 2 ? null : [0, 1, 2].map((m) => {
          const u = ((s - tPid) * 0.5 + i * 0.13 + m * 0.33) % 1;
          const px = POS[i].x + Math.sin(u * 6 + i) * 24, py = POS[i].y - POS[i].e * 400 - u * 520;
          return <circle key={i + '_' + m} cx={px} cy={py} r={6 + 3 * Math.sin(u * 5)} fill="#ffe2a8" opacity={Math.sin(u * Math.PI) * 0.9 * rp(s, tPid, tPid + 0.5) * (1 - rp(s, tUnica, tUnica + 1.2))} />;
        }))}
        {/* pensamiento: su angel */}
        {th > 0.01 && (
          <g transform={`translate(${POS[0].x - 30} ${POS[0].y - POS[0].e * 650 - 150}) scale(${th})`} opacity={th}>
            <circle cx={0} cy={0} r={90} fill="rgba(255,250,235,0.92)" /><circle cx={-70} cy={30} r={60} fill="rgba(255,250,235,0.92)" /><circle cx={70} cy={30} r={60} fill="rgba(255,250,235,0.92)" />
            <circle cx={-60} cy={150} r={20} fill="rgba(255,250,235,0.9)" /><circle cx={-40} cy={210} r={11} fill="rgba(255,250,235,0.9)" />
            <path d="M-40 -10Q-90 -70 -110 -10Q-70 -20 -40 20Z" fill="#cfe0ff" /><path d="M40 -10Q90 -70 110 -10Q70 -20 40 20Z" fill="#cfe0ff" />
            <path d="M-22 60Q-30 0 0 -20Q30 0 22 60Z" fill="#ffffff" stroke="#bcd0ff" strokeWidth={4} />
            <circle cx={0} cy={-34} r={16} fill="#ffffff" stroke="#ffe08a" strokeWidth={5} />
          </g>
        )}
        {/* la Biblia guarda su nombre */}
        {s > tBiblia - 0.1 && s < tNombre + 1.2 && (() => {
          const b = rp(s, tBiblia, tBiblia + 0.6);
          const cx = rx(s), cy = ry(s) - rodeE * 740 - 60 + Math.sin(s * 2.5) * 8;
          return (
            <g transform={`translate(${cx} ${cy}) scale(${b})`} opacity={b}>
              <Glow cx={0} cy={0} r={200} color="#ffe2a8" op={0.9} />
              <path d="M0 20Q-60 -10 -120 10V-70Q-60 -90 0 -60Z" fill="#fff6d8" stroke="#d9a84a" strokeWidth={5} />
              <path d="M0 20Q60 -10 120 10V-70Q60 -90 0 -60Z" fill="#fffbe8" stroke="#d9a84a" strokeWidth={5} />
              <path d="M-100 -20Q-60 -40 -20 -20M-100 0Q-60 -20 -20 0M100 -20Q60 -40 20 -20M100 0Q60 -20 20 0" stroke="rgba(217,168,74,0.6)" strokeWidth={5} fill="none" />
            </g>
          );
        })()}
        {/* polvo dorado en espiral */}
        {s > tGuardo - 0.1 && s < tNombre + 1.4 && Array.from({length: 34}).map((_, i) => {
          const u = (s - tGuardo + 0.1);
          const ang = u * 7 + i * 0.55;
          const rad = (230 - 70 * rp(s, tGuardo, tNombre + 0.9)) * (0.5 + 0.5 * h(i));
          const cx = rx(s) + Math.cos(ang) * rad, cy = ry(s) - 260 - 160 * Math.sin(i * 0.9) + Math.sin(ang) * rad * 0.35 - u * 30;
          return <circle key={i} cx={cx} cy={cy} r={4 + 3 * h(i * 3)} fill="#ffe08a" opacity={0.9 * rp(s, tGuardo - 0.1, tGuardo + 0.3)} />;
        })}
        <rect width={2400} height={2600} fill="#fff8e4" opacity={puertaAb * 0.85} style={{mixBlendMode: 'screen'}} />
      </svg>
    </AbsoluteFill>
  );
};

// ---------- el guion completo ----------
export const Escena: React.FC = () => {
  const {s} = useS();
  const opA = vis(s, -1, tCarcel + 0.9);
  const opB = vis(s, tCarcel - 0.1, tPu2 + 0.6);
  const opC = vis(s, tPu2 - 0.4, tOr + 0.3);
  const opS = vis(s, tOr - 0.7, tNombre + 1.0);
  const opH = vis(s, tNombre, DUR + 1);
  // pantalla dividida (Mientras discutian ... Pedro seguia afuera)
  const pk = rp(s, tMientras - 0.1, tMientras + 0.8) * (1 - rp(s, tFijate - 0.3, tFijate + 0.6));
  const corte = lerp(1920, 1130, pk);
  const cenY = lerp(1000, 735, pk);
  const KA = Array.from({length: 9}).map((_, k) => T(0) + 0.15 + k * 0.55);
  const KP = Array.from({length: 12}).map((_, k) => tMientras + k * 0.55);
  const a0 = rp(s, tNombre + 0.5, tNombre + 1.8);
  return (
    <AbsoluteFill style={{background: '#070a1c'}}>
      <Sc op={opA} s={s}>
        <Camara paradas={[{t: T(0), x: 540, y: 1000, zoom: 1.0}, {t: tCarcel, x: 470, y: 1150, zoom: 1.22}, {t: tCarcel + 0.9, x: 470, y: 1150, zoom: 1.3}]}>
          <Fachada s={s} modo="toca" a0={0} kt={KA} />
        </Camara>
      </Sc>
      <Sc op={opB} s={s}>
        <Camara
          paradas={[
            {t: tCarcel - 0.2, x: 540, y: 1000, zoom: 1.0}, {t: tDormido, x: 540, y: 1000, zoom: 1.12}, {t: tDos1 - 0.15, x: 300, y: 1060, zoom: 1.45},
            {t: tSold, x: 790, y: 1060, zoom: 1.45}, {t: tAtado, x: 540, y: 1120, zoom: 1.9}, {t: tCad1 + 0.5, x: 540, y: 1130, zoom: 2.1},
            {t: tDia - 0.1, x: 780, y: 800, zoom: 1.35}, {t: tHer, x: 560, y: 1050, zoom: 1.05}, {t: tMat + 0.3, x: 560, y: 1060, zoom: 1.12},
            {t: tAng + 0.2, x: 640, y: 1050, zoom: 1.35}, {t: tDesp + 0.6, x: 560, y: 1120, zoom: 1.5}, {t: tCad2, x: 540, y: 1150, zoom: 1.9},
            {t: tCay + 1.0, x: 540, y: 1180, zoom: 1.9}, {t: tPu2 - 0.2, x: 560, y: 1250, zoom: 1.0},
          ]}
        >
          <Celda s={s} />
        </Camara>
      </Sc>
      <Sc op={opC} s={s}>
        <Camara
          paradas={[
            {t: tPu2 - 0.5, x: 560, y: 1150, zoom: 1.25}, {t: tHie, x: 560, y: 1100, zoom: 1.4}, {t: tCiu, x: 560, y: 1000, zoom: 0.8},
            {t: tAbr, x: 560, y: 1100, zoom: 1.0}, {t: tCam, x: 600, y: 1200, zoom: 1.0}, {t: tFue, x: 650, y: 1200, zoom: 1.0},
            {t: tFue + 1.8, x: 1500, y: 1150, zoom: 1.0}, {t: tMaria + 1.0, x: 1850, y: 1100, zoom: 1.1}, {t: tOr + 0.3, x: WIN.x, y: WIN.y, zoom: 9.0},
          ]}
        >
          <Calle s={s} />
        </Camara>
      </Sc>
      <Sc op={opS} s={s}>
        <div style={{position: 'absolute', left: 0, top: 0, width: 1080, height: 1920, clipPath: `inset(0px 0px ${1920 - corte}px 0px)`}}>
          <Camara
            centroY={cenY}
            paradas={[
              {t: tOr - 0.8, x: 700, y: 1250, zoom: 1.5}, {t: tOr + 0.5, x: 640, y: 1160, zoom: 1.15}, {t: tSalio, x: 700, y: 1200, zoom: 1.2},
              {t: tRode + 0.2, x: 1450, y: 1200, zoom: 1.25}, {t: tAleg, x: 1520, y: 1120, zoom: 1.7}, {t: tCorrio, x: 1450, y: 1150, zoom: 1.5},
              {t: tAdentro + 0.6, x: 800, y: 1200, zoom: 1.2}, {t: tY, x: 640, y: 1250, zoom: 1.2}, {t: tEstas, x: 600, y: 1280, zoom: 1.4},
              {t: tInsist + 0.4, x: 760, y: 1230, zoom: 1.4}, {t: tAng2 + 0.2, x: 700, y: 1150, zoom: 1.3}, {t: tMientras, x: 650, y: 1320, zoom: 1.0},
              {t: tFijate - 0.3, x: 660, y: 1320, zoom: 1.0}, {t: tFijate + 0.9, x: 700, y: 1250, zoom: 1.35}, {t: tUnica + 0.5, x: 700, y: 1170, zoom: 1.7},
              {t: tBiblia, x: 700, y: 1130, zoom: 2.0}, {t: tNombre + 0.3, x: 720, y: 1180, zoom: 1.8}, {t: tNombre + 0.9, x: 1500, y: 1250, zoom: 1.5},
            ]}
          >
            <Sala s={s} />
          </Camara>
        </div>
        {pk > 0.01 && (
          <div style={{position: 'absolute', left: 0, top: corte, width: 1080, height: 1920 - corte, overflow: 'hidden'}}>
            <div style={{position: 'absolute', left: 0, top: (1 - pk) * 260, width: 1080, height: 790, overflow: 'hidden'}}>
              <div style={{position: 'absolute', left: 0, top: 0, width: 1080, height: 1920, transformOrigin: '0 0', transform: 'translate(135px, -375px) scale(0.75)'}}>
                <Fachada s={s} modo="toca" a0={0} kt={KP} />
              </div>
            </div>
          </div>
        )}
        {pk > 0.01 && <div style={{position: 'absolute', left: 0, top: corte - 5, width: 1080, height: 10, background: 'linear-gradient(90deg, rgba(255,226,168,0), rgba(255,226,168,0.95), rgba(255,226,168,0))', opacity: pk, boxShadow: '0 0 40px rgba(255,226,168,0.9)'}} />}
      </Sc>
      <Sc op={opH} s={s}>
        <Camara
          paradas={[
            {t: tNombre, x: 420, y: 1300, zoom: 1.8}, {t: tNombre + 1.8, x: 420, y: 1250, zoom: 1.5}, {t: tSorp + 0.2, x: 420, y: 1250, zoom: 1.35},
            {t: tToque + 0.3, x: 420, y: 1200, zoom: 1.0}, {t: tCrees, x: 430, y: 1150, zoom: 0.5}, {t: tOramos, x: 440, y: 1100, zoom: 0.44}, {t: DUR, x: 440, y: 1040, zoom: 0.38},
          ]}
        >
          <Fachada s={s} modo="abrazo" a0={a0} kt={[tNO]} vecT={tToque} />
        </Camara>
      </Sc>
      <Rayos s={s} op={0.12} x={-160 + 40 * Math.sin(s * 0.2)} />
      <Polvo s={s} />
      <Luz s={s} t={tCarcel + 0.4} color="rgba(190,215,255,0.9)" />
      <Luz s={s} t={tAng + 0.2} />
      <Luz s={s} t={tPu2 + 0.1} />
      <Luz s={s} t={tOr - 0.1} color="rgba(255,196,120,0.9)" />
      <Luz s={s} t={tNombre + 0.6} />
      <AbsoluteFill style={{background: 'radial-gradient(circle at 50% 52%, rgba(0,0,0,0) 58%, rgba(0,0,12,0.5) 100%)'}} />
    </AbsoluteFill>
  );
};
